extern int	graphical_printf(char *, char *, ...);
extern int	dialog(char *, float, float, float, int);
extern void	wait_test_exit(void);
extern void	sleep(int);
extern void	print_date_time(void);
extern sprite_info_t	*draw_thick_vline(float, float, float, float, float, int, int);
extern int	font_set;				/* 0x801694cc */
extern int	(*sw_select)(void), (*sw_back)(void);
extern menu_item_t	additional_items[];		/* adjust.c: the ADDITIONAL ADJUSTMENTS */
extern int	D_8015cba4;				/* set: no CLEAR AUDITS item */

int	show_audits(int);
int	clear_credits(int);
int	clear_all_audits(int);
int	adjust_value(int), adjust_list(int), adjust_enable(int), adjust_yes_no(int);
void	adjust_help(int);
static int	adjust_list_set(int);

char	audit_title[128];				/* 0x80172e38 */
char	adjust_setting_text[128];			/* 0x80172eb8 */
menu_t	*adjust_list_menu;				/* 0x80172ba8 */
menu_item_t	*adjust_list_items;			/* 0x80172bac */
menu_item_t	clear_audit_items[32];			/* 0x80172bb8 */

/* 0x8010acf0: read AUDITS.FMT into the AUDITS and CLEAR AUDITS menus */
int load_audits(char *file)
{
	char	buf[128];
	menu_item_t	*item;
	int	i;

	yyin = fopen(file, "r");
	if(!yyin)
	{
		fprintf(stderr, "Can not open file: %s\r\n", file);
		return 0;
	}
	yylex();
	fclose(yyin);
	for(item = audit_items; item->name; item++)
	{
		item->kind = MENU_FUNC;
		item->target = show_audits;
	}
	i = num_audit_items;
	if(!D_8015cba4)
	{
		audit_items[i].name = "CLEAR AUDITS";
		audit_items[i].target = &clear_audits_menu;
		audit_items[i].kind = MENU_SUB;
		audit_items[i].help = help_clear_assorted;
		audit_items[i].hook = 0;
	}
	i++;
	audit_items[i].name = "EXIT";
	audit_items[i].kind = MENU_EXIT;
	audit_items[i].target = 0;
	audit_items[i].help = "RETURN TO PREVIOUS MENU";
	audit_items[i].hook = 0;
	i++;
	audit_items[i].name = 0;
	audit_items[i].kind = -1;
	audit_items[i].target = 0;
	audit_items[i].help = 0;
	audit_items[i].hook = 0;

	for(i = 0; i < num_audit_items; i++)
	{
		graphical_printf(buf, "CLEAR %s", audit_items[i].name);
		clear_audit_items[i].name = malloc(strlen(buf) + 1);
		if(!clear_audit_items[i].name)
		{
			fprintf(stderr, "Can not allocate memory for \"%s\" memu item string\r\n", buf);
			return 0;
		}
		memcpy(clear_audit_items[i].name, buf, strlen(buf) + 1);
		clear_audit_items[i].kind = MENU_FUNC;
		clear_audit_items[i].target = clear_credits;
		clear_audit_items[i].help = 0;
		clear_audit_items[i].hook = 0;
	}
	clear_audit_items[i].name = "CLEAR ALL";
	clear_audit_items[i].kind = MENU_FUNC;
	clear_audit_items[i].target = clear_all_audits;
	clear_audit_items[i].help = "CLEAR ALL AUDITS";
	clear_audit_items[i].hook = 0;
	i++;
	clear_audit_items[i].name = "EXIT";
	clear_audit_items[i].kind = MENU_EXIT;
	clear_audit_items[i].target = 0;
	clear_audit_items[i].help = "RETURN TO AUDITS MENU";
	clear_audit_items[i].hook = 0;
	i++;
	clear_audit_items[i].name = 0;
	clear_audit_items[i].kind = -1;
	clear_audit_items[i].target = 0;
	clear_audit_items[i].help = 0;
	clear_audit_items[i].hook = 0;
	return 1;
}

/* 0x8010b0e0: read ADJUST.FMT into the ADDITIONAL ADJUSTMENTS menu */
int load_adjustments(char *file)
{
	adjust_fmt_t	*a;
	menu_item_t	*item;

	yyin = fopen(file, "r");
	if(!yyin)
	{
		fprintf(stderr, "Can not open file: %s\r\n", file);
		return 0;
	}
	yylex();
	fclose(yyin);
	for(a = additional_adjustments, item = additional_items; a; a = a->next)
	{
		if(a->name)
		{
			item->name = a->name;
			item->kind = MENU_FUNC;
			if(a->control == 0)
				item->target = adjust_value;
			else if(a->control == 1)
				item->target = adjust_list;
			else if(a->control == 2)
				item->target = adjust_enable;
			else if(a->control == 4)
				item->target = adjust_yes_no;
			item->help = adjust_text;
			item->hook = adjust_help;
			item++;
		}
	}
	item->name = "EXIT";
	item->kind = MENU_EXIT;
	item->target = 0;
	item->help = "RETURN TO ADJUSTMENTS MENU";
	item->hook = 0;
	item++;
	item->name = 0;
	item->kind = -1;
	item->target = 0;
	item->help = 0;
	item->hook = 0;
	return 1;
}

/* 0x8010b260 */
int dump_audits(void)
{
	int	i;

	draw_title("DUMP AUDITS");
	set_text_font(1);
	set_text_color(0xffffffff);
	set_text_justification_mode(HJUST_CENTER|VJUST_CENTER);
	set_text_position(hres / 2.0F, vres / 2.0F, 1.0F);
	oprintf("BEGIN CAPTURE TO SERIAL PORT NOW");
	message_box("PRESS TEST OR START TO BEGIN DUMP", -1.0F, 5.0F, 1.0F);
	while(!sw_select() && !sw_back())
		sleep(1);
	snd_scall_bank("ttest", 15, 180, 127, 0x8000);
	while(sw_select() || sw_back())
		sleep(1);
	delete_multiple_strings(0, 0);
	del1c(0, 0);
	sleep(1);
	draw_title("DUMP AUDITS");
	set_text_font(1);
	set_text_color(0xffffffff);
	set_text_justification_mode(HJUST_CENTER|VJUST_CENTER);
	set_text_position(hres / 2.0F, vres / 2.0F + 8.0F, 1.0F);
	oprintf("DUMPING AUDITS");
	set_text_position(hres / 2.0F, vres / 2.0F - 8.0F, 1.0F);
	oprintf("PLEASE WAIT");
	sleep(1);
	fprintf(stderr, "\n");
	fprintf(stderr, "CARNEVIL");
	fprintf(stderr, " AUDITS\n");
	print_date_time();
	fprintf(stderr, "\n");
	for(i = 0; i < num_audit_items + 1; i++)
	{
		delete_multiple_strings(1, 1);
		set_string_id(1);
		set_text_font(1);
		set_text_color(0xffffffff);
		set_text_justification_mode(HJUST_CENTER|VJUST_CENTER);
		set_text_position(hres / 2.0F, vres / 2.0F - 40.0F, 1.0F);
		oprintf("DUMPING PAGE %d OF %d", i + 1, num_audit_items + 1);
		snd_scall_bank("ttest", 12, 180, 127, 0x8000);
		sleep(1);
		show_audits(-(i + 1));
		fprintf(stderr, "\n");
	}
	fprintf(stderr, "\nEND OF DUMP\n\n");
	snd_scall_bank("ttest", 11, 180, 127, 0x8000);
	delete_multiple_strings(0, 0);
	del1c(0, 0);
	return 0;
}

/* 0x8010b66c: an AUDITS menu item's audits, a page at a time (n < 0: dump item -n - 1 to
   the serial port) */
int show_audits(int n)
{
	audit_fmt_t	*pages[16];
	int	value, denom;
	audit_fmt_t	*a;
	int	dump, page, column, color, last, i;
	int	days, hours, mins;
	float	x, y, colw, bottom;

	column = 1;
	page = 1;
	dump = 0;
	last = 0;
	denom = 0;
	audit_color_index = 0;
	color = -1;
	if(n < 0)
	{
		n = -n - 1;
		dump = 1;
	}
	a = audit_lists[n];
	if(!dump)
	{
		graphical_printf(audit_title, "%s - PAGE: %d", audit_items[n].name, 1);
		draw_title(audit_title);
	}
	else
	{
		for(i = 0; i < 20 - strlen(audit_items[n].name) / 2; i++)
			fprintf(stderr, " ");
		fprintf(stderr, "%s\n----------------------------------------\n", audit_items[n].name);
	}
	y = vres - font0_height * 3.5F;
	colw = hres / (float)a->columns;
	bottom = vres * 0.1F;
	if(a->columns > 1 && !dump)
	{
		for(x = colw; x < (float)a->columns * colw; x += colw)
			draw_thick_vline(x - 1.0F, y, bottom, 1.0F, 3.0F, -1, 0);
	}
	x = 0.0F;
	pages[page - 1] = a;
	while(a)
	{
		if(a->prompt)
		{
			if(y < bottom && !dump)
			{
				if(++column > a->columns)
				{
new_page:
					del1c(0x4900, -1);
					if(page == 1)
						message_box("UP - NEXT / BUTTON - EXIT", -1.0F, 5.0F, 1.0F);
					else if(!last)
						message_box("UP - NEXT / DOWN - PREV / BUTTON - EXIT", -1.0F, 5.0F, 1.0F);
					else
						message_box("DOWN - PREV / BUTTON - EXIT", -1.0F, 5.0F, 1.0F);
wait:
					while(!sw_up() && !sw_down() && !sw_select())
						sleep(1);
					if(sw_down() && page > 1)
					{
						delete_multiple_strings(0x4f00, -1);
						page--;
						a = pages[page - 1];
						y = vres - font0_height * 3.5F;
						x = 0.0F;
						column = 1;
						last = 0;
					}
					else if(sw_down())
					{
						while(sw_down())
							sleep(1);
						goto wait;
					}
					else if(sw_up() && !last)
					{
						delete_multiple_strings(0x4f00, -1);
						pages[page++] = a;
						column = 1;
						y = vres - font0_height * 3.5F;
						x = 0.0F;
					}
					else if(sw_up())
					{
						while(sw_up())
							sleep(1);
						goto wait;
					}
					else if(sw_select())
					{
						delete_multiple_strings(0, 0);
						del1c(0, 0);
						return 0;
					}
					while(sw_up() || sw_down() || sw_select())
						sleep(1);
					del1c(0x5400, -1);
					graphical_printf(audit_title, "%s - PAGE: %d", audit_items[n].name, page);
					draw_title(audit_title);
				}
				else
				{
					x = colw * (float)(column - 1);
					y = vres - font0_height * 3.5F;
				}
			}
			set_string_id(0x4f00);
			if(a->prompt_adjust == 0)
				set_text_justification_mode(HJUST_LEFT|VJUST_TOP);
			else if(a->prompt_adjust == 2)
				set_text_justification_mode(HJUST_LEFT|VJUST_TOP);
			else if(a->prompt_adjust == 1)
				set_text_justification_mode(HJUST_RIGHT|VJUST_TOP);
			else
				set_text_justification_mode(HJUST_CENTER|VJUST_TOP);
			set_text_font(a->font);
			if(a->prompt_color == 1)
				audit_color_index = 1;
			if(audit_color_index)
			{
				if(++color > 1)
					color = 0;
				set_text_color(audit_colors[color]);
			}
			else
				set_text_color(a->prompt_color);
			if(a->type == 6)
				set_text_position((float)a->px, (float)a->py, 1.0F);
			else if(a->px < 0)
				set_text_position(x + colw * 0.05F, y, 1.0F);
			else
				set_text_position(x + (float)a->px, (float)a->py, 1.0F);
			if(!dump)
				oprintf(a->prompt);
			else
				fprintf(stderr, "%-30s", a->prompt);
			if(a->audit_adjust == 0)
				set_text_justification_mode(HJUST_RIGHT|VJUST_TOP);
			else if(a->audit_adjust == 2)
				set_text_justification_mode(HJUST_LEFT|VJUST_TOP);
			else if(a->audit_adjust == 1)
				set_text_justification_mode(HJUST_RIGHT|VJUST_TOP);
			else
				set_text_justification_mode(HJUST_CENTER|VJUST_TOP);
			if(audit_color_index)
				set_text_color(audit_colors[color]);
			else
				set_text_color(a->audit_color);
			if(a->prompt_color == 0xff)
				audit_color_index = 0;
			if(a->ax < 0)
				set_text_position(x + colw - colw * 0.05F, y, 1.0F);
			else
				set_text_position(x + (float)a->ax, (float)a->ay, 1.0F);
			if(a->type != 6)
			{
				if(get_audit(a->audit, &value) ||
					((a->type == 8 || a->type == 9 || a->type == 10) && get_audit(a->denom, &denom)))
					set_text_color(0xffff0000);
				switch(a->type)
				{
					case 9:
						if(denom)
							denom = value / denom;
						if(!dump)
						{
							oprintf("%d", denom);
							if(a->ax < 0)
								set_text_position((float)(-audit_columns[font_set][a->font] * 9) + (x + colw) - colw * 0.05F, y, 1.0F);
							else
								set_text_position((float)(-audit_columns[font_set][a->font] * 9) + x + (float)a->ax, (float)a->ay, 1.0F);
							oprintf("(%d)", value);
						}
						else
							fprintf(stderr, "(%7d) %7d\n", value, denom);
						break;
					case 8:
						if(denom)
							denom = (value * 100) / denom;
						if(!dump)
						{
							oprintf("%d %%", denom);
							if(a->ax < 0)
								set_text_position((float)(-audit_columns[font_set][a->font] * 9) + (x + colw) - colw * 0.05F, y, 1.0F);
							else
								set_text_position((float)(-audit_columns[font_set][a->font] * 9) + x + (float)a->ax, (float)a->ay, 1.0F);
							oprintf("(%d)", value);
						}
						else
							fprintf(stderr, "(%7d) %7d %%\n", value, denom);
						break;
					case 10:
						if(denom)
							value = value / denom;
						else
							value = 0;
						days = value / 86400;
						value %= 86400;
						hours = value / 3600;
						value %= 3600;
						mins = value / 60;
						value %= 60;
						if(days)
						{
							if(!dump)
								oprintf("%2d  %02d:%02d:%02d", days, hours, mins, value);
							else
								fprintf(stderr, "%2d  %02d:%02d:%02d\n", days, hours, mins, value);
						}
						else
						{
							if(!dump)
								oprintf("%02d:%02d:%02d", hours, mins, value);
							else
								fprintf(stderr, "%02d:%02d:%02d\n", hours, mins, value);
						}
						break;
					case 7:
						if(!dump)
							oprintf("%d %%", value);
						else
							fprintf(stderr, "%d %%\n", value);
						break;
					case 0:
						if(!dump)
							oprintf("%d", value);
						else
							fprintf(stderr, "%d\n", value);
						break;
					case 1:
						if(!dump)
							oprintf("$ %3.2f", (float)value / 100.0F);
						else
							fprintf(stderr, "$ %3.2f\n", (float)value / 100.0F);
						break;
					case 3:
						if(!dump)
							oprintf("0x%08.8X", value);
						else
							fprintf(stderr, "0x%08.8X\n", value);
						break;
					case 4:
						if(!dump)
							oprintf("%f", *(float *)&value);
						else
							fprintf(stderr, "%f\n", (float)value);
						break;
					case 5:
						days = value / 86400;
						value %= 86400;
						hours = value / 3600;
						value %= 3600;
						mins = value / 60;
						value %= 60;
						if(days)
						{
							if(!dump)
								oprintf("%2d  %02d:%02d:%02d", days, hours, mins, value);
							else
								fprintf(stderr, "%2d  %02d:%02d:%02d\n", days, hours, mins, value);
						}
						else
						{
							if(!dump)
								oprintf("%02d:%02d:%02d", hours, mins, value);
							else
								fprintf(stderr, "%02d:%02d:%02d\n", hours, mins, value);
						}
						break;
					case 2:
						break;
					default:
						fprintf(stderr, "Unrecognized conversion type: %d\r\n", a->type);
						break;
				}
			}
			if(!a->linespace)
				y -= (float)get_font_height(a->font) * 2.0F;
			else
				y -= (float)(get_font_height(a->font) + a->linespace);
		}
		a = a->next;
	}
	if(page != 1)
	{
		last = 1;
		goto new_page;
	}
	if(dump)
		return 0;
	wait_test_exit();
	delete_multiple_strings(0, 0);
	del1c(0, 0);
	return 0;
}

/* 0x8010c644: CLEAR <item>: clear the audits of AUDITS menu item n */
int clear_credits(int n)
{
	char	buf[128];
	int	val;
	audit_fmt_t	*a;

	graphical_printf(buf, "ARE YOU SURE YOU WANT TO %s", clear_audit_items[n].name);
	val = dialog(buf, -1.0F, -1.0F, 1.0F, 3);
	if(val != 1)
	{
		graphical_printf(buf, "%s NOT CLEARED", audit_items[n].name);
		message_box(buf, -1.0F, -1.0F, 1.0F);
	}
	else
	{
		for(a = audit_lists[n]; a; a = a->next)
		{
			set_audit(a->audit, 0);
			if(get_audit(a->audit, &val))
			{
				fprintf(stderr, "Problem clearing audit number: %d\r\n", a->audit);
				return 0;
			}
		}
		graphical_printf(buf, "%s CLEARED", audit_items[n].name);
		message_box(buf, -1.0F, -1.0F, 1.0F);
	}
	wait_test_exit();
	clear_message_box();
	return 0;
}

/* 0x8010c7cc: CLEAR ALL (n < 0: without asking) */
int clear_all_audits(int n)
{
	char	buf[128];
	int	val;
	int	i, quiet;

	quiet = 0;
	if(n < 0)
	{
		quiet = 1;
		val = 1;
	}
	else
	{
		graphical_printf(buf, "ARE YOU SURE YOU WANT TO CLEAR ALL AUDITS");
		val = dialog(buf, -1.0F, -1.0F, 1.0F, 3);
	}
	if(val != 1)
	{
		graphical_printf(buf, "AUDITS NOT CLEARED");
		message_box(buf, -1.0F, -1.0F, 1.0F);
		wait_test_exit();
		clear_message_box();
	}
	else
	{
		for(i = 0; i < cmos_config.max_audits; i++)
		{
			set_audit(i, 0);
			if(get_audit(i, &val))
			{
				fprintf(stderr, "Problem clearing audit number: %d\r\n", i);
				return 0;
			}
		}
		if(!quiet)
		{
			graphical_printf(buf, "ALL AUDITS CLEARED");
			message_box(buf, -1.0F, -1.0F, 1.0F);
			wait_test_exit();
			clear_message_box();
		}
	}
	return 0;
}

/* 0x8010c914: CONTROL 0, a number from MIN to MAX */
int adjust_value(int n)
{
	char	buf[80];
	int	val;
	adjust_fmt_t	*a;
	int	delay;

	delay = 30;
	for(a = additional_adjustments; a; a = a->next)
		if(n == a->index)
			break;
	if(!a)
		return 0;
	graphical_printf(buf, "ADJUSTING %s", a->name);
	draw_title(buf);
	message_box("USE STICK TO CHANGE VALUE/BUTTON TO SET AND EXIT", -1.0F, 5.0F, 1.0F);
	set_text_font(0);
	set_text_justification_mode(HJUST_CENTER|VJUST_CENTER);
	set_text_position(hres / 2.0F, vres / 2.0F, 1.0F);
	set_text_color(0xffffffff);
	set_string_id(0x4f00);
	if(get_adjustment(a->adjustment, &val))
	{
		set_adjustment(a->adjustment, a->def);
		get_adjustment(a->adjustment, &val);
	}
	else if(val < a->min || val > a->max)
	{
		set_adjustment(a->adjustment, a->def);
		get_adjustment(a->adjustment, &val);
	}
	oprintf("%d", val);
	do
	{
		sleep(1);
		if(sw_up() || sw_down())
		{
			if(sw_up())
			{
				if(++val > a->max)
					val = a->max;
				else
					snd_scall_bank("ttest", 12, 180, 127, 0x8000);
			}
			else
			{
				if(--val < a->min)
					val = a->min;
				else
					snd_scall_bank("ttest", 13, 180, 127, 0x8000);
			}
			set_adjustment(a->adjustment, val);
			delete_multiple_strings(0x4f00, -1);
			set_text_font(0);
			set_text_justification_mode(HJUST_CENTER|VJUST_CENTER);
			set_text_position(hres / 2.0F, vres / 2.0F, 1.0F);
			set_text_color(0xffffffff);
			set_string_id(0x4f00);
			oprintf("%d", val);
			while(--delay && (sw_up() || sw_down()))
				sleep(1);
			if(sw_8() || sw_select() || sw_back())
				delay = 10;
			else
				delay = 30;
		}
	} while(!sw_select() && !sw_back());
	while(sw_select() || sw_back())
		sleep(1);
	delete_multiple_strings(0x4f00, -1);
	clear_menu();
	snd_scall_bank("ttest", 11, 180, 127, 0x8000);
	return 0;
}

/* 0x8010d5cc: an item of a CONTROL 1 list */
static int adjust_list_set(int i)
{
	char	buf[80];

	set_adjustment(cur_adjustment->adjustment, i);
	graphical_printf(buf, "%s SET TO %s", adjust_list_menu->title, adjust_list_items[i].name);
	message_box(buf, -1.0F, -1.0F, 1.0F);
	wait_test_exit();
	return -1;
}

/* 0x8010cd08: CONTROL 1, a menu of the LISTITEMs */
int adjust_list(int n)
{
	char	buf[80];
	int	val;
	adjust_fmt_t	*a;
	int	i;

	for(a = additional_adjustments; a; a = a->next)
		if(n == a->index)
			break;
	if(!a)
		return 0;
	cur_adjustment = a;
	adjust_list_menu = malloc(sizeof(menu_t));
	if(adjust_list_menu)
	{
		adjust_list_items = malloc((a->length + 2) * sizeof(menu_item_t));
		if(adjust_list_items)
		{
			adjust_list_menu->title = a->list_title;
			adjust_list_menu->x = -1.0F;
			adjust_list_menu->y = -1.0F;
			if(get_adjustment(a->adjustment, &val) || val < a->min || val >= a->max)
				adjust_list_menu->sel = 0;
			else
				adjust_list_menu->sel = val;
			adjust_list_menu->items = adjust_list_items;
			for(i = 0; i < a->length; i++)
			{
				adjust_list_items[i].name = a->list_items[i];
				adjust_list_items[i].kind = MENU_FUNC;
				adjust_list_items[i].target = adjust_list_set;
				graphical_printf(buf, "SET \033%dc%s\033%dc TO \033%dc%s", 0xffffffff, a->list_title,
					0xff00ffff, 0xffffffff, a->list_items[i]);
				adjust_list_items[i].help = malloc(strlen(buf) + 1);
				if(adjust_list_items[i].help)
					strcpy(adjust_list_items[i].help, buf);
				adjust_list_items[i].hook = 0;
			}
			adjust_list_items[i].name = "EXIT";
			adjust_list_items[i].kind = MENU_EXIT;
			adjust_list_items[i].help = "RETURN TO ADDITIONAL ADJUSTMENTS MENU";
			adjust_list_items[i].target = 0;
			adjust_list_items[i].hook = 0;
			adjust_list_items[i + 1].name = 0;
			adjust_list_items[i + 1].kind = -1;
			adjust_list_items[i + 1].target = 0;
			adjust_list_items[i + 1].help = 0;
			adjust_list_items[i + 1].hook = 0;
			do_menu(adjust_list_menu);
			for(i = 0; i < a->length; i++)
				if(adjust_list_items[i].help)
					free(adjust_list_items[i].help);
			free(adjust_list_items);
		}
		else
			fprintf(stderr, "Can not allocate memory for adjust list items\r\n");
		free(adjust_list_menu);
	}
	else
		fprintf(stderr, "Can not allocate memory for adjust list\r\n");
	return 0;
}

/* 0x8010d030: CONTROL 2, ENABLED/DISABLED */
int adjust_enable(int n)
{
	char	buf[128];
	int	val;
	adjust_fmt_t	*a;

	a = additional_adjustments;
	if(a)
	{
		for(; a; a = a->next)
			if(n == a->index)
				break;
		if(!a)
			return 0;
		if(get_adjustment(a->adjustment, &val) || val < 0 || val > 1)
		{
			set_adjustment(a->adjustment, a->def);
			graphical_printf(buf, "%s WAS \033%dcINVALID\033%dc - RESTORED TO FACTORY SETTING", a->name,
				0xffff0000, 0xff00ffff);
			message_box(buf, -1.0F, -1.0F, 1.0F);
		}
		else
		{
			if(val)
				graphical_printf(buf, "%s ENABLED - DO YOU WANT TO DISABLE ?", a->name);
			else
				graphical_printf(buf, "%s DISABLED - DO YOU WANT TO ENABLE ?", a->name);
			if(dialog(buf, -1.0F, -1.0F, 1.0F, 3) == 1)
			{
				if(val)
					set_adjustment(a->adjustment, 0);
				else
					set_adjustment(a->adjustment, 1);
			}
		}
	}
	clear_menu();
	return 0;
}

/* 0x8010d18c: CONTROL 4, YES/NO */
int adjust_yes_no(int n)
{
	char	buf[128];
	int	val;
	adjust_fmt_t	*a;

	a = additional_adjustments;
	if(a)
	{
		for(; a; a = a->next)
			if(n == a->index)
				break;
		if(!a)
			return 0;
		if(get_adjustment(a->adjustment, &val) || val < 0 || val > 1)
		{
			set_adjustment(a->adjustment, a->def);
			graphical_printf(buf, "%s WAS \033%dcINVALID\033%dc - RESTORED TO FACTORY SETTING", a->name,
				0xffff0000, 0xff00ffff);
			message_box(buf, -1.0F, -1.0F, 1.0F);
		}
		else
		{
			graphical_printf(buf, "%s", a->name);
			if(dialog(buf, -1.0F, -1.0F, 1.0F, 3) == 1)
				set_adjustment(a->adjustment, 1);
			else
				set_adjustment(a->adjustment, 0);
		}
	}
	clear_menu();
	return 0;
}

/* 0x8010d2bc: the help line of ADDITIONAL ADJUSTMENT n, with its current setting */
void adjust_help(int n)
{
	int	val;
	adjust_fmt_t	*a;
	int	valid;

	for(a = additional_adjustments; a; a = a->next)
		if(n == a->index)
			break;
	if(!a)
		return;
	valid = 1;
	if(get_adjustment(a->adjustment, &val))
		valid = 0;
	else if(a->control == 2 || a->control == 4)
	{
		if(val < 0 || val > 1)
			valid = 0;
	}
	else if(a->control == 1)
	{
		if(val < a->min || val >= a->max)
			valid = 0;
	}
	else if(val < a->min || val > a->max)
		valid = 0;
	if(a->control == 0)
		graphical_printf(adjust_text, "SET %s ", a->name);
	else if(a->control == 1)
		graphical_printf(adjust_text, "SELECT %s ", a->name);
	else if(a->control == 2)
		graphical_printf(adjust_text, "ENABLE/DISABLE %s ", a->name);
	else if(a->control == 4)
		graphical_printf(adjust_text, "%s ", a->name);
	if(!valid)
	{
		graphical_printf(adjust_setting_text, "\033%dc(CURRENT SETTING IS INVALID)", 0xffff0000);
		strcat(adjust_text, adjust_setting_text);
		return;
	}
	if(a->control == 2)
	{
		if(val)
			graphical_printf(adjust_setting_text, "\033%dc(CURRENT SETTING - \033%dcENABLED\033%dc)",
				0xff00ff00, 0xffffffff, 0xff00ff00);
		else
			graphical_printf(adjust_setting_text, "\033%dc(CURRENT SETTING - \033%dcDISABLED\033%dc)",
				0xff00ff00, 0xffffffff, 0xff00ff00);
	}
	else if(a->control == 4)
	{
		if(val)
			graphical_printf(adjust_setting_text, "\033%dc(CURRENT SETTING - \033%dcYES\033%dc)",
				0xff00ff00, 0xffffffff, 0xff00ff00);
		else
			graphical_printf(adjust_setting_text, "\033%dc(CURRENT SETTING - \033%dcNO\033%dc)",
				0xff00ff00, 0xffffffff, 0xff00ff00);
	}
	else if(a->control == 0)
		graphical_printf(adjust_setting_text, "\033%dc(CURRENT SETTING - \033%dc%d\033%dc)",
			0xff00ff00, 0xffffffff, val, 0xff00ff00);
	else if(a->control == 1)
		graphical_printf(adjust_setting_text, "\033%dc(CURRENT SETTING - \033%dc%s\033%dc)",
			0xff00ff00, 0xffffffff, a->list_items[val], 0xff00ff00);
	strcat(adjust_text, adjust_setting_text);
}
